def fig(id, mid, section, slug, scaffold, size, title, content, alt, desc, goal, why, abbrevs=None):
    return dict(id=id, mid=mid, section=section, stem=f"{P}-{mid}-{slug}", scaffold=scaffold, size=size, title=title,
                content=content, alt=alt, desc=desc, goal=goal, why=why, abbrevs=abbrevs or [])


